    }
    return null;
  }

  function extractTarget(href) {
    var current = href;
    for (var d = 0; d < 5; d++) {
      var p;
      try { p = new URL(current); } catch (e) { return null; }

      var found = null;
      for (var i = 0; i < PARAM_NAMES.length; i++) {
        var raw = p.searchParams.get(PARAM_NAMES[i]);
