  }

  function extractAppeal(root) {
    // outerHTML 里 &amp; / &#x2f; 未还原，不先解码则 new URL 取不到 url 参数
    return extractAppealFromText(decodeEntities(root.outerHTML)) || extractAppealFromAnchors(root);
