    return null;
  }

  function scanDom() {
    var root = document.documentElement;
    if (!root) return false;
    // 先按“申请恢复”的 base64 还原（唯一可靠的目标来源），再退回正文扫描；
    // 正文扫描必须同时覆盖 outerHTML（脚本内文本）与 textContent（实体已解码）
    var u = extractAppeal(root) ||
      scanText(decodeEntities(root.outerHTML)) ||
