        nodes[i].click();
        return;
      }
    }
  }
  document.addEventListener('DOMContentLoaded', function () {
    clickContinue();
    var c = setInterval(clickContinue, 300);
    setTimeout(function () { clearInterval(c); }, 8000);
  });
