(function () {
  'use strict';

  /* ============================================================
   * 0. 运行环境
   * ============================================================ */
  const W = (typeof unsafeWindow !== 'undefined' && unsafeWindow) || window;
  const HOST = location.hostname;
  const IS_YT = /(^|\.)youtube\.com$/i.test(HOST);
  const IS_BILI = /(^|\.)bilibili\.com$/i.test(HOST);
  if (!IS_YT && !IS_BILI) return;

  const HAS_GM = typeof GM_xmlhttpRequest === 'function';
  const VERSION = '1.2.0';
  const TAG = '[视频下载器]';
  const log = (...a) => console.log('%c' + TAG, 'color:#00aeec;font-weight:bold', ...a);

  /* ============================================================
   * 1. 通用工具
   * ============================================================ */
  function fmtBytes(n) {
    if (!n || n <= 0 || !isFinite(n)) return '—';
    const u = ['B', 'KB', 'MB', 'GB', 'TB'];
    let i = 0;
    let v = n;
    while (v >= 1024 && i < u.length - 1) { v /= 1024; i++; }
    return (v >= 100 ? v.toFixed(0) : v.toFixed(1)) + ' ' + u[i];
  }

  function safeName(s, max) {
    const out = String(s || 'video')
      .replace(/[\\/:*?"<>|\u0000-\u001f]/g, '_')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, max || 100)
      .replace(/[.\s]+$/, '');
    return out || 'video';
  }

  function copyText(text) {
    const done = () => UI.toast('已复制到剪贴板');
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, () => fallbackCopy(text));
    } else {
      fallbackCopy(text);
    }
  }

  function fallbackCopy(text) {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0;';
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand('copy');
      UI.toast('已复制到剪贴板');
    } catch (e) {
      UI.toast('复制失败，请手动选择');
    }
    ta.remove();
  }

  function pad2(n) {
    return String(n).padStart(2, '0');
  }

  // 秒 → SRT 时间轴 00:00:01,200
  function srtTime(sec) {
    const ms = Math.max(0, Math.round((Number(sec) || 0) * 1000));
    const h = Math.floor(ms / 3600000);
    const m = Math.floor((ms % 3600000) / 60000);
    const s = Math.floor((ms % 60000) / 1000);
    const r = ms % 1000;
    return pad2(h) + ':' + pad2(m) + ':' + pad2(s) + ',' + String(r).padStart(3, '0');
  }

  // 文本落地（字幕用）：加 BOM，避免部分播放器把中文当 GBK
  function saveText(filename, text, mime) {
    const blob = new Blob(['\ufeff' + text], { type: (mime || 'text/plain') + ';charset=utf-8' });
    const href = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = href;
    a.download = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(href), 60000);
    UI.toast('已保存：' + filename);
  }

  function extFromUrl(url, dft) {
    const m = String(url || '').split('?')[0].match(/\.([a-z0-9]{2,5})$/i);
    return m ? m[1].toLowerCase() : dft || 'jpg';
  }

  /* ============================================================
   * 2. 网络请求（走扩展，绕过页面 CORS，可带 cookie / Referer）
   * ============================================================ */
  function request(url, opt) {
    opt = opt || {};
    return new Promise((resolve, reject) => {
      if (!HAS_GM) {
        reject(new Error('缺少 GM_xmlhttpRequest 权限，请在油猴管理面板检查脚本权限'));
        return;
      }
      GM_xmlhttpRequest({
        method: opt.method || 'GET',
        url: url,
        headers: opt.headers || {},
        data: opt.data,
        timeout: opt.timeout || 30000,
        responseType: opt.responseType || 'text',
        anonymous: opt.anon === true,
        onload: (r) => {
          if (r.status >= 200 && r.status < 400) resolve(r);
          else reject(new Error('HTTP ' + r.status + ' @ ' + url.split('?')[0]));
        },
        onerror: () => reject(new Error('网络错误 @ ' + url.split('?')[0])),
        ontimeout: () => reject(new Error('请求超时 @ ' + url.split('?')[0])),
      });
    });
  }

  async function requestJSON(url, opt) {
    const r = await request(url, opt);
    const txt = typeof r.responseText === 'string' ? r.responseText : String(r.response || '');
    try {
      return JSON.parse(txt);
    } catch (e) {
      throw new Error('返回内容不是 JSON（可能被风控拦截）');
    }
  }

  /* ============================================================
   * 3. 下载落地：GM_download 优先，失败降级为内存中转
   * ============================================================ */
  function download(url, filename, referer) {
    if (!url) { UI.toast('没有可用地址'); return; }
    const headers = referer ? { Referer: referer } : {};

    if (typeof GM_download === 'function') {
      let started = false;
      try {
        GM_download({
          url: url,
          name: filename,
          headers: headers,
          saveAs: false,
          onload: () => { started = true; },
          onprogress: () => { started = true; },
          onerror: (e) => {
            console.warn(TAG, 'GM_download 失败，改用中转下载', e);
            if (!started) relayDownload(url, filename, headers);
            else UI.toast('下载中断：' + filename);
          },
          ontimeout: () => { if (!started) relayDownload(url, filename, headers); },
        });
        UI.toast('已开始下载：' + filename);
        return;
      } catch (e) {
        console.warn(TAG, 'GM_download 调用异常', e);
      }
    }
    relayDownload(url, filename, headers);
  }

  function relayDownload(url, filename, headers) {
    UI.toast('正在中转下载，大文件请耐心等待…');
    GM_xmlhttpRequest({
      method: 'GET',
      url: url,
      headers: headers || {},
      responseType: 'arraybuffer',
      anonymous: false,
      timeout: 0,
      onload: (r) => {
        if (r.status < 200 || r.status >= 400) {
          UI.toast('下载失败：HTTP ' + r.status);
          return;
        }
        const blob = new Blob([r.response], { type: 'application/octet-stream' });
        const href = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = href;
        a.download = filename;
        a.style.display = 'none';
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(href), 120000);
        UI.toast('已保存：' + filename);
      },
      onerror: () => UI.toast('下载失败：网络错误'),
      ontimeout: () => UI.toast('下载超时'),
