      fab:
        'position:fixed;right:18px;bottom:96px;width:54px;height:54px;border-radius:50%;border:0;padding:0;margin:0;' +
        'background:#0b7fd4;color:#fff;font:700 13px/1.2 ' + FONT + ';display:none;align-items:center;justify-content:center;' +
        'text-align:center;cursor:pointer;z-index:2147483647;box-shadow:0 6px 18px rgba(0,0,0,.35);',
