      act: 'font-size:11.5px;padding:6px 10px;border-radius:7px;border:1px solid #3a4152;background:#232936;color:#cfd7e6;cursor:pointer;',
      empty: 'padding:22px 14px;font-size:12px;color:#8b93a5;text-align:center;line-height:1.7;',
      emptyErr: 'padding:22px 14px;font-size:12px;color:#ff8b8b;text-align:center;line-height:1.7;',
      toast:
        'position:fixed;right:18px;bottom:250px;max-width:320px;padding:8px 12px;border-radius:8px;' +
        'background:#14161c;color:#e8eaf0;font-size:12px;line-height:1.5;border:1px solid #3a4152;' +
        'z-index:2147483648;opacity:0;transition:opacity .18s;pointer-events:none;',
    };

    function init(h) {
