      const closeBtn = mk('button', S.close, '×');
      closeBtn.type = 'button';
      closeBtn.title = '收起';
      closeBtn.addEventListener('click', hide);
      head.appendChild(titleEl);
      head.appendChild(tagEl);
      head.appendChild(closeBtn);

      hintEl = mk('div', S.hint);
      hintEl.style.display = 'none';
      listEl = mk('div', S.list);
      footEl = mk('div', S.foot);

      panel.appendChild(head);
      panel.appendChild(hintEl);
      panel.appendChild(listEl);
      panel.appendChild(footEl);
      root.appendChild(panel);

      toastEl = mk('div', S.toast);
      root.appendChild(toastEl);

      mount();
      layout();
      bindScroll();
    }

    function mount() {
      const parent = document.body || document.documentElement;
      if (!parent) return;
      if (host.parentNode !== parent) parent.appendChild(host);
    }

    function bindScroll() {
      if (scrollBound) return;
      scrollBound = true;
      const onMove = () => {
        if (posMode !== 'fixed') layout();
      };
      window.addEventListener('scroll', onMove, { passive: true });
      window.addEventListener('resize', onMove);
    }

    function layout() {
      if (!fab) return;
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const sy = window.pageYOffset || document.documentElement.scrollTop || 0;

      if (posMode === 'fixed') {
        fab.style.position = 'fixed';
        fab.style.right = '18px';
        fab.style.bottom = '96px';
        fab.style.left = 'auto';
        fab.style.top = 'auto';
        if (panel) {
          panel.style.position = 'fixed';
          panel.style.right = '18px';
          panel.style.bottom = '162px';
          panel.style.left = 'auto';
          panel.style.top = 'auto';
          panel.style.maxHeight = '68vh';
        }
      } else {
        // 兜底：祖先带 filter/transform 时 fixed 会失效，改用绝对定位并跟随滚动
        const size = 54;
        fab.style.position = 'absolute';
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
        fab.style.left = Math.max(8, vw - 18 - size) + 'px';
        fab.style.top = Math.round(sy + vh - 96 - size) + 'px';
        if (panel) {
          const ph = panel.offsetHeight || 320;
          panel.style.position = 'absolute';
          panel.style.right = 'auto';
          panel.style.bottom = 'auto';
          panel.style.maxHeight = 'none';
          panel.style.left = Math.max(8, vw - 18 - 400) + 'px';
          panel.style.top = Math.round(Math.max(sy + 8, sy + vh - 162 - ph)) + 'px';
        }
        if (toastEl) {
          toastEl.style.position = 'absolute';
          toastEl.style.bottom = 'auto';
          toastEl.style.top = Math.round(sy + vh - 250) + 'px';
        }
      }
    }

    function inViewport(el) {
      if (!el) return false;
      const r = el.getBoundingClientRect();
      return r.width > 20 && r.height > 20 && r.bottom > 0 && r.top < window.innerHeight && r.right > 0 && r.left < window.innerWidth;
    }

    // 显示后量一次：不在视野内就切兜底定位
    function verifyPosition() {
      if (!fab || fab.style.display === 'none') return;
      if (!window.innerWidth || !window.innerHeight) return;
      if (posMode === 'fixed' && !inViewport(fab)) {
        posMode = 'absolute';
        log('检测到 position:fixed 被页面样式影响，已切换绝对定位兜底');
        layout();
      }
    }

    function showFab() {
      if (!fab) return;
      if (!fabShown) {
        fabShown = true;
        fab.style.display = 'flex';
        layout();
      }
      setTimeout(verifyPosition, 200);
      setTimeout(verifyPosition, 1200);
    }

    function hideFab() {
      if (!fab) return;
      fabShown = false;
      fab.style.display = 'none';
    }

    function show() {
      open = true;
      if (!panel) return;
      panel.style.display = 'flex';
      layout();
      setTimeout(() => {
        if (posMode !== 'fixed') layout();
        verifyPosition();
      }, 0);
    }

    function hide() {
      open = false;
      if (panel) panel.style.display = 'none';
      if (posMode !== 'fixed') layout();
    }

    function isOpen() {
      return open;
    }

    function toast(msg) {
      if (!toastEl) return;
      toastEl.textContent = msg;
      toastEl.style.opacity = '1';
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        toastEl.style.opacity = '0';
      }, 2800);
    }

    function clearBody() {
      listEl.textContent = '';
      footEl.textContent = '';
      footEl.style.display = 'none';
      hintEl.textContent = '';
      hintEl.style.display = 'none';
    }

    function setLoading(msg) {
      hasContent = false;
      if (!listEl) return;
      titleEl.textContent = '解析中…';
      tagEl.textContent = '';
      clearBody();
      listEl.appendChild(mk('div', S.empty, msg || '正在获取播放信息…'));
    }

    function setError(msg) {
      hasContent = false;
      if (!listEl) return;
      clearBody();
      listEl.appendChild(mk('div', S.emptyErr, msg));
      if (handlers.onReload) {
        const b = mk('button', S.act, '重新解析');
        b.type = 'button';
        b.addEventListener('click', () => handlers.onReload());
        footEl.appendChild(b);
        footEl.style.display = 'flex';
      }
    }

    function makeRow(item) {
      const row = mk('div', S.row);
      const meta = mk('div', S.meta);
      const lbl = mk('div', S.lbl, item.label);
      lbl.title = item.label;
      meta.appendChild(lbl);
      if (item.sub) meta.appendChild(mk('div', S.sub, item.sub));

      const btns = mk('div', S.btns);
      const dl = mk('button', S.btnPri, '下载');
      dl.type = 'button';
      dl.addEventListener('click', () => {
        if (item.onDownload) item.onDownload();
        else download(item.url, item.filename, item.referer);
      });
      btns.appendChild(dl);

      if (item.url) {
        const cp = mk('button', S.btn, '直链');
        cp.type = 'button';
        cp.title = '复制下载地址';
        cp.addEventListener('click', () => copyText(item.url));
        btns.appendChild(cp);
      }

      row.appendChild(meta);
      row.appendChild(btns);
      return row;
    }

    function render(model) {
      hasContent = true;
      clearBody();
      titleEl.textContent = model.title || '视频下载器';
      titleEl.title = model.title || '';
      tagEl.textContent = model.tag || '';

      if (model.hint) {
        hintEl.textContent = model.hint;
        hintEl.style.display = 'block';
      }

      const groups = (model.groups || []).filter((g) => g.items && g.items.length);
      if (!groups.length) {
        listEl.appendChild(mk('div', S.empty, model.emptyText || '没有解析到可下载的媒体流。'));
      }
      groups.forEach((g) => {
        const wrap = mk('div', '');
        wrap.appendChild(mk('div', S.gtitle, g.title));
        g.items.forEach((item) => wrap.appendChild(makeRow(item)));
        listEl.appendChild(wrap);
      });

      (model.actions || []).forEach((a) => {
        const b = mk('button', S.act, a.label);
        b.type = 'button';
        b.addEventListener('click', a.onClick);
        footEl.appendChild(b);
      });
      if (handlers.onReload) {
        const b = mk('button', S.act, '刷新');
        b.type = 'button';
        b.addEventListener('click', () => handlers.onReload());
        footEl.appendChild(b);
      }
      if (footEl.childNodes.length) footEl.style.display = 'flex';

      layout();
    }

    return {
      init: init,
      mount: mount,
      showFab: showFab,
      hideFab: hideFab,
      show: show,
      hide: hide,
      isOpen: isOpen,
      toast: toast,
      setLoading: setLoading,
      setError: setError,
      render: render,
      reset: function () {
        hasContent = false;
      },
      debug: function () {
        const r = fab ? fab.getBoundingClientRect() : null;
        return {
          version: VERSION,
          mounted: !!(host && host.isConnected),
          parent: host && host.parentNode && host.parentNode.nodeName,
          fabDisplay: fab && fab.style.display,
          posMode: posMode,
          rect: r ? { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) } : null,
          viewport: { w: window.innerWidth, h: window.innerHeight, scrollY: Math.round(window.pageYOffset) },
          bodyFilter: document.body ? getComputedStyle(document.body).filter : null,
          htmlFilter: document.documentElement ? getComputedStyle(document.documentElement).filter : null,
        };
      },
    };
  })();

  /* ============================================================
   * 5. 哔哩哔哩
   * ============================================================ */
  const BILI_QN = {
    127: '8K 超高清', 126: '杜比视界', 125: 'HDR 真彩', 120: '4K 超清',
    116: '1080P60', 112: '1080P+', 80: '1080P 高清', 74: '720P60',
    64: '720P 高清', 32: '480P 清晰', 16: '360P 流畅', 6: '240P 极速',
  };
  const BILI_CODEC = { 7: 'AVC/H.264', 12: 'HEVC/H.265', 13: 'AV1' };
  const BILI_REFERER = 'https://www.bilibili.com/';

  function isBiliPgc() {
    return /\/bangumi\/play\//.test(location.pathname);
  }

  async function biliMeta() {
    const href = location.href;
    const pMatch = href.match(/[?&]p=(\d+)/);
    const pageIdx = pMatch ? Math.max(1, parseInt(pMatch[1], 10)) : 1;

    if (isBiliPgc()) {
      const ep = (href.match(/\/ep(\d+)/) || [])[1];
      const ss = (href.match(/\/ss(\d+)/) || [])[1];
      if (!ep && !ss) throw new Error('无法识别番剧集数（ep/ss）');
      const q = ep ? 'ep_id=' + ep : 'season_id=' + ss;
      const j = await requestJSON('https://api.bilibili.com/pgc/view/web/season?' + q, {
        headers: { Referer: BILI_REFERER },
      });
      const res = j.result || j.data;
      if (!res) throw new Error(j.message || '番剧信息接口无数据');
      const eps = res.episodes || [];
      if (!eps.length) throw new Error('该番剧没有可播放的集数');
      const cur = ep ? (eps.find((e) => String(e.ep_id) === ep) || eps[0]) : eps[0];
      return {
        epId: String(cur.ep_id),
        cid: cur.cid,
        bvid: cur.bvid,
        title: (res.season_title || res.title || document.title) + ' ' + (cur.title || ''),
        duration: cur.duration ? Math.round(cur.duration / 1000) : 0,
        pgc: true,
        pic: cur.cover || res.cover || '',
      };
    }

    const bvid = (href.match(/\/video\/(BV[0-9A-Za-z]+)/) || [])[1];
    const aid = (href.match(/\/video\/av(\d+)/i) || [])[1];
    if (!bvid && !aid) throw new Error('无法识别视频号（BV/av）');

    const j = await requestJSON(
      'https://api.bilibili.com/x/web-interface/view?' + (bvid ? 'bvid=' + bvid : 'aid=' + aid),
      { headers: { Referer: BILI_REFERER } }
    );
    if (j.code !== 0 || !j.data) throw new Error(j.message || '视频信息接口返回 ' + j.code);
    const d = j.data;
    const pages = d.pages || [];
    const idx = Math.min(pageIdx, pages.length || 1);
    const pg = pages[idx - 1] || {};
    let title = d.title || document.title;
    if ((pages.length || 1) > 1) title += ' P' + idx + (pg.part ? ' ' + pg.part : '');
    return {
      bvid: d.bvid,
      aid: d.aid,
      cid: pg.cid || d.cid,
      title: title,
      duration: pg.duration || d.duration || 0,
      pgc: false,
      partCount: pages.length || 1,
      partIdx: idx,
      pic: d.pic || '',
    };
  }

  async function biliPlayUrl(meta) {
    const base = meta.pgc
      ? 'https://api.bilibili.com/pgc/player/web/playurl?ep_id=' + meta.epId
      : 'https://api.bilibili.com/x/player/playurl?bvid=' + meta.bvid + '&cid=' + meta.cid;
    const url = base + '&qn=127&fnval=4048&fourk=1&fnver=0';
    const j = await requestJSON(url, { headers: { Referer: BILI_REFERER } });
    const d = meta.pgc ? (j.result || j.data) : j.data;
    if (!d) throw new Error(j.message || '取流接口返回 ' + j.code + '（可能需要登录/大会员）');
    return d;
  }

  async function biliMuxedUrl(meta) {
    const base = meta.pgc
      ? 'https://api.bilibili.com/pgc/player/web/playurl?ep_id=' + meta.epId
      : 'https://api.bilibili.com/x/player/playurl?bvid=' + meta.bvid + '&cid=' + meta.cid;
    try {
      const j = await requestJSON(base + '&qn=80&fnval=1&fnver=0&fourk=1', {
        headers: { Referer: BILI_REFERER },
      });
      const d = meta.pgc ? (j.result || j.data) : j.data;
      if (d && d.durl && d.durl.length === 1 && d.durl[0].url) {
        return { url: d.durl[0].url, quality: d.quality, size: d.durl[0].size || 0 };
      }
    } catch (e) {
      log('整合版取流失败（忽略）', e.message);
    }
    return null;
  }

  function biliVideoLabel(v) {
    const h = v.height ? v.height + 'P' : (BILI_QN[v.id] || '未知');
    const fps = v.frameRate ? (Math.abs(v.frameRate - 30) > 3 ? Math.round(v.frameRate) + 'fps' : '') : '';
    return [h, fps, BILI_CODEC[v.codecid] || ('codec ' + v.codecid)].filter(Boolean).join(' · ');
  }

  /* 字幕：x/player/v2 → data.subtitle.subtitles[].subtitle_url（协议相对，必须要 Referer） */
  async function biliSubtitleTracks(meta) {
    try {
      const q = meta.bvid && meta.cid ? 'bvid=' + meta.bvid + '&cid=' + meta.cid : 'ep_id=' + meta.epId;
      const j = await requestJSON('https://api.bilibili.com/x/player/v2?' + q, {
        headers: { Referer: BILI_REFERER },
      });
      if (j.code !== 0) {
        log('字幕接口返回', j.code, j.message);
        return [];
      }
      const box = (j.data && j.data.subtitle) || {};
      return (box.subtitles || [])
        .filter((s) => s && s.subtitle_url)
        .map((s) => ({
          lan: s.lan || 'und',
          name: s.lan_doc || s.lan || '字幕',
          ai: !!s.ai_type,
          url: s.subtitle_url.indexOf('//') === 0 ? 'https:' + s.subtitle_url : s.subtitle_url,
        }));
    } catch (e) {
      log('字幕列表获取失败（忽略）', e.message);
      return [];
    }
  }

  // B站字幕 JSON（body[{from,to,content}]）→ SRT
  function biliJsonToSrt(j) {
    const body = (j && j.body) || [];
    const out = [];
    body.forEach((it, i) => {
      const text = String(it.content || '').replace(/\r/g, '').trim();
      if (!text) return;
      out.push(String(i + 1));
      out.push(srtTime(it.from) + ' --> ' + srtTime(it.to));
      out.push(text);
      out.push('');
    });
    return out.join('\n');
  }

  async function saveBiliSubtitle(track, filename) {
    UI.toast('正在获取字幕：' + track.name);
    try {
      const j = await requestJSON(track.url, { headers: { Referer: BILI_REFERER } });
      const srt = biliJsonToSrt(j);
      if (!srt.trim()) {
        UI.toast('该字幕内容为空');
        return;
      }
      saveText(filename, srt);
    } catch (e) {
      UI.toast('字幕获取失败：' + e.message);
    }
  }

  async function buildBiliModel() {
    UI.setLoading('正在读取视频信息…');
    const meta = await biliMeta();
    const base = safeName(meta.title);

    UI.setLoading('正在获取播放地址…');
    const play = await biliPlayUrl(meta);
    const dash = play.dash || {};
    const duration = meta.duration || 0;

    const muxedItems = [];
    const mux = await biliMuxedUrl(meta);
    if (mux) {
      muxedItems.push({
        label: '整合版（含音轨，单文件）· ' + (BILI_QN[mux.quality] || mux.quality || ''),
        sub: [fmtBytes(mux.size), 'MP4', mux.quality ? 'qn ' + mux.quality : ''].filter(Boolean).join(' · '),
        url: mux.url,
        filename: base + '_整合版.mp4',
        referer: BILI_REFERER,
      });
    }

    const videoItems = (dash.video || [])
      .slice()
      .sort((a, b) => (b.height || 0) - (a.height || 0) || (b.bandwidth || 0) - (a.bandwidth || 0))
      .map((v) => {
        const est = duration && v.bandwidth ? Math.round((v.bandwidth / 8) * duration) : 0;
        const h = v.height ? v.height + 'p' : 'video';
        const codecKey = v.codecid === 12 ? 'hevc' : v.codecid === 13 ? 'av1' : 'avc';
        return {
          label: biliVideoLabel(v),
          sub: [est ? '约 ' + fmtBytes(est) : '体积未知', (v.bandwidth / 1000 | 0) + ' kbps', '无音轨'].join(' · '),
          url: v.baseUrl || v.base_url,
          filename: base + '_' + h + '_' + codecKey + '.mp4',
          referer: BILI_REFERER,
          _h: v.height || 0,
        };
      });

    const audioItems = (dash.audio || [])
      .slice()
      .sort((a, b) => (b.bandwidth || 0) - (a.bandwidth || 0))
      .map((a) => {
        const est = duration && a.bandwidth ? Math.round((a.bandwidth / 8) * duration) : 0;
        const name = a.id === 30250 ? '杜比全景声' : a.id === 30251 ? 'Hi-Res 无损' : a.id >= 30280 ? '192K' : a.id >= 30232 ? '132K' : '64K';
        return {
          label: name + ' · ' + (a.codecs || ''),
          sub: [est ? '约 ' + fmtBytes(est) : '体积未知', (a.bandwidth / 1000 | 0) + ' kbps', '无画面'].join(' · '),
          url: a.baseUrl || a.base_url,
          filename: base + '_audio_' + (a.id || 0) + '.m4a',
          referer: BILI_REFERER,
          _bw: a.bandwidth || 0,
        };
      });

    const bestV = videoItems[0];
    const bestA = audioItems[0];

    // 字幕与封面（字幕需要登录，失败不影响主流程）
    UI.setLoading('正在获取字幕与封面…');
    const tracks = await biliSubtitleTracks(meta);
    const subItems = tracks.map((t) => {
      const fn = base + '_' + t.lan + '.srt';
      return {
        label: t.name + (t.ai ? '（AI 生成）' : ''),
        sub: 'SRT · ' + t.lan,
        url: t.url,
        filename: fn,
        onDownload: () => saveBiliSubtitle(t, fn),
      };
    });

    const coverItems = [];
    if (meta.pic) {
      const picUrl = meta.pic.indexOf('//') === 0 ? 'https:' + meta.pic : meta.pic;
      const ext = extFromUrl(picUrl, 'jpg');
      coverItems.push({
        label: '封面原图',
        sub: ext.toUpperCase() + ' · 视频封面',
        url: picUrl,
        filename: base + '_封面.' + ext,
        referer: BILI_REFERER,
      });
    }

    const actions = [];
    if (bestV && bestA) {
      actions.push({
        label: '下载最佳画面 + 声音',
        onClick: () => {
          download(bestV.url, bestV.filename, BILI_REFERER);
          setTimeout(() => download(bestA.url, bestA.filename, BILI_REFERER), 1200);
          copyText('ffmpeg -i "' + bestV.filename + '" -i "' + bestA.filename + '" -c copy "' + base + '_合并.mp4"');
          UI.toast('已开始下载两路流，并复制了合并命令');
        },
      });
      actions.push({
        label: '复制 ffmpeg 合并命令',
        onClick: () => copyText('ffmpeg -i "' + bestV.filename + '" -i "' + bestA.filename + '" -c copy "' + base + '_合并.mp4"'),
      });
    }
    if (meta.pgc) {
      actions.push({ label: '复制 yt-dlp 命令', onClick: () => copyText('yt-dlp -f "bv*+ba/b" "' + location.href.split('?')[0] + '"') });
    } else if (meta.bvid) {
      actions.push({
        label: '复制 yt-dlp 命令',
        onClick: () => copyText('yt-dlp -f "bv*+ba/b" "https://www.bilibili.com/video/' + meta.bvid + (meta.partCount > 1 ? '?p=' + meta.partIdx : '') + '"'),
      });
    }

    const hintParts = [];
    if (!muxedItems.length) hintParts.push('当前视频没有可用的「整合版」单文件，需分别下载画面与声音后合并（面板底部可复制 ffmpeg 命令）。');
    else hintParts.push('「整合版」是单个可直接播放的 MP4，画质通常止步 1080P；更高画质只能走分离流 + 合并。');
    if (!play.dash) hintParts.push('未返回 DASH 流，可能需要在页面登录后再刷新。');
    if (!subItems.length) hintParts.push('没有拿到字幕：B站字幕要先在页面登录，且视频本身得带 CC 或 AI 字幕。');

    return {
      title: meta.title,
      tag: '哔哩哔哩',
      hint: hintParts.join(' '),
      groups: [
        { title: '整合版（画面 + 声音）', items: muxedItems },
        { title: '仅画面（DASH）', items: videoItems },
        { title: '仅声音（DASH）', items: audioItems },
        { title: '字幕', items: subItems },
        { title: '封面', items: coverItems },
      ],
      actions: actions,
      emptyText: '没有解析到可下载的流。请确认已在页面登录，或该视频为付费/地区限制内容。',
    };
  }

  /* ============================================================
   * 6. YouTube
   * ============================================================ */
  function getYtId() {
    try {
      const u = new URL(location.href);
      if (u.pathname === '/watch') return u.searchParams.get('v');
      const m = u.pathname.match(/^\/(?:shorts|embed|live)\/([A-Za-z0-9_-]{6,})/);
      return m ? m[1] : null;
    } catch (e) {
      return null;
    }
  }

  function readEmbeddedPlayerResponse() {
    try {
      const pr = W.ytInitialPlayerResponse;
      if (pr && pr.streamingData) return pr;
    } catch (e) { /* ignore */ }
    return null;
  }

  function ytApiKey() {
    try {
      if (W.ytcfg && typeof W.ytcfg.get === 'function') {
        const k = W.ytcfg.get('INNERTUBE_API_KEY');
        if (k) return k;
      }
      if (W.ytcfg && W.ytcfg.data_ && W.ytcfg.data_.INNERTUBE_API_KEY) return W.ytcfg.data_.INNERTUBE_API_KEY;
    } catch (e) { /* ignore */ }
    return null;
  }

  // 用 ANDROID 客户端调 innertube：多数情况下返回不带 signatureCipher 的直链
  async function ytAndroidPlayer(videoId) {
    const key = ytApiKey();
    if (!key) throw new Error('页面未提供 INNERTUBE_API_KEY');
    const ua = 'com.google.android.youtube/19.44.38 (Linux; U; Android 11) gzip';
    const body = {
      context: {
        client: {
          clientName: 'ANDROID',
          clientVersion: '19.44.38',
          androidSdkVersion: 30,
          userAgent: ua,
          hl: 'en',
          gl: 'US',
          utcOffsetMinutes: -new Date().getTimezoneOffset(),
        },
      },
      videoId: videoId,
      contentCheckOk: true,
      racyCheckOk: true,
    };
    const j = await requestJSON('https://www.youtube.com/youtubei/v1/player?key=' + encodeURIComponent(key) + '&prettyPrint=false', {
      method: 'POST',
      anon: false,
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': ua,
        'X-Youtube-Client-Name': '3',
        'X-Youtube-Client-Version': '19.44.38',
        'Origin': 'https://www.youtube.com',
      },
      data: JSON.stringify(body),
    });
    if (!j.streamingData) {
      const st = (j.playabilityStatus && j.playabilityStatus.status) || 'UNKNOWN';
      throw new Error('ANDROID 客户端未返回流（' + st + '）');
    }
    return j;
  }

  function collectYtFormats(pr) {
    const sd = pr.streamingData || {};
    const all = [].concat(sd.formats || [], sd.adaptiveFormats || []);
    const out = { muxed: [], video: [], audio: [] };
    const seen = new Set();
    let ciphered = 0;

    all.forEach((f) => {
      let url = f.url || '';
      if (!url && (f.signatureCipher || f.cipher)) {
        ciphered++;
        return; // 签名加密的直链无法在浏览器内直接还原
      }
      if (!url) return;

      const mime = (f.mimeType || '').split(';')[0];
      const codecs = ((f.mimeType || '').match(/codecs="([^"]+)"/) || [])[1] || '';
      const isAudio = mime.indexOf('audio/') === 0;
      const isWebm = mime.indexOf('webm') >= 0;
      const ext = isWebm ? 'webm' : mime.indexOf('mp4') >= 0 ? 'mp4' : 'bin';
      const key = f.itag
        ? 'itag:' + f.itag
        : (isAudio ? 'a' : 'v') + '|' + (f.height || 0) + '|' + (f.fps || 0) + '|' + codecs + '|' + (f.bitrate || 0);
      if (seen.has(key)) return;
      seen.add(key);

      const size = Number(f.contentLength || 0);
      const ql = f.qualityLabel || '';
      const fps = f.fps && f.fps > 35 ? ' ' + Math.round(f.fps) + 'fps' : '';
      const kbps = f.bitrate ? (Math.round(f.bitrate / 1000) + ' kbps') : '';

      const item = {
        label: isAudio ? (kbps || '音频') + ' · ' + codecs : (ql || (f.height ? f.height + 'p' : 'video')) + fps + ' · ' + codecs,
        sub: [size ? fmtBytes(size) : '体积未知', isAudio ? '音频' : '视频', f.itag ? 'itag ' + f.itag : ''].filter(Boolean).join(' · '),
        url: url,
        filename: '',
        referer: 'https://www.youtube.com/',
        _h: f.height || 0,
        _bitrate: f.bitrate || 0,
        _ext: ext,
        _audio: isAudio,
      };

      if (isAudio) out.audio.push(item);
      else if (f.audioQuality || f.audioBitrate) out.muxed.push(item);
      else out.video.push(item);
    });

    out.muxed.sort((a, b) => b._h - a._h || b._bitrate - a._bitrate);
    out.video.sort((a, b) => b._h - a._h || b._bitrate - a._bitrate);
    out.audio.sort((a, b) => b._bitrate - a._bitrate);
    return { groups: out, ciphered: ciphered };
  }

  /* 字幕：captions.playerCaptionsTracklistRenderer.captionTracks[].baseUrl（timedtext） */
  function ytCaptionTracks(pr) {
    const tr = pr && pr.captions && pr.captions.playerCaptionsTracklistRenderer;
    const list = (tr && tr.captionTracks) || [];
    return list
      .filter((t) => t && t.baseUrl)
      .map((t) => {
        const nm =
          (t.name && (t.name.simpleText || (t.name.runs && t.name.runs[0] && t.name.runs[0].text))) ||
          t.languageCode ||
          '字幕';
        const auto = t.kind === 'asr' || /auto-generated/i.test(nm);
        return {
          lan: t.languageCode || 'und',
          name: nm + (auto ? '（自动生成）' : ''),
          auto: auto,
          url: t.baseUrl.replace(/&fmt=[^&]*/g, ''),
        };
      });
  }

  // YouTube json3 → SRT
  function ytJson3ToSrt(j) {
    const evs = (j && j.events) || [];
    const rows = [];
    evs.forEach((e) => {
      if (!e.segs) return;
      const text = e.segs
        .map((s) => s.utf8 || '')
        .join('')
        .replace(/\s*\n+\s*/g, ' ')
        .replace(/\s{2,}/g, ' ')
        .trim();
      if (!text) return;
      const start = (e.tStartMs || 0) / 1000;
      const dur = e.dDurationMs ? e.dDurationMs / 1000 : 0;
      if (dur <= 0) return;
      rows.push({ start: start, end: start + dur, text: text });
    });
    const out = [];
    let last = -1;
    rows.forEach((r, i) => {
      const start = Math.max(r.start, last);
      last = Math.max(last, r.end);
      out.push(String(i + 1));
      out.push(srtTime(start) + ' --> ' + srtTime(r.end));
      out.push(r.text);
      out.push('');
    });
    return out.join('\n');
  }

  async function ytCaptionFile(url) {
    const sep = url.indexOf('?') >= 0 ? '&' : '?';
    let json3 = null;
    try {
      const r = await request(url + sep + 'fmt=json3', {
        headers: { Referer: 'https://www.youtube.com/' },
      });
      json3 = JSON.parse(r.responseText);
    } catch (e) {
      json3 = null;
    }
    if (json3 && json3.events && json3.events.length) {
      const srt = ytJson3ToSrt(json3);
      if (srt.trim()) return { text: srt, ext: 'srt' };
    }
    const r2 = await request(url + sep + 'fmt=vtt', {
      headers: { Referer: 'https://www.youtube.com/' },
    });
    const vtt = String(r2.responseText || '');
    if (!vtt.trim() || vtt.indexOf('Error') === 0) throw new Error('字幕内容为空或接口拒绝');
    return { text: vtt, ext: 'vtt' };
  }

  function ytCoverItems(details, vid, base) {
    const list = [];
    const seen = new Set();
    const thumbs = ((details.thumbnail && details.thumbnail.thumbnails) || [])
      .slice()
      .sort((a, b) => (b.width || 0) - (a.width || 0));

    const push = (url, w, h) => {
      if (!url || seen.has(url)) return;
      seen.add(url);
      list.push({
        label: w ? w + '×' + h : '封面',
        sub: 'JPG · 封面图',
        url: url,
        filename: base + '_封面_' + (w ? w + 'x' + h : 'cover') + '.jpg',
        referer: 'https://www.youtube.com/',
      });
    };

    // maxresdefault 有时不存在，放在最前面，失败就换下面列表
    if (!thumbs.some((t) => (t.width || 0) >= 1200)) push('https://i.ytimg.com/vi/' + vid + '/maxresdefault.jpg', 1280, 720);
    thumbs.forEach((t) => push(t.url, t.width, t.height));
    return list;
  }

  async function buildYtModel() {
    const vid = getYtId();
    if (!vid) throw new Error('无法识别视频 ID');

    UI.setLoading('正在获取播放数据（ANDROID 接口）…');

    let pr = null;
    let source = '';
    const errors = [];

    try {
      pr = await ytAndroidPlayer(vid);
      source = 'ANDROID 接口';
    } catch (e) {
      errors.push(e.message);
      log('ANDROID 接口失败', e.message);
    }

    if (!pr) {
      UI.setLoading('正在读取页面内嵌播放数据…');
      const embedded = readEmbeddedPlayerResponse();
      if (embedded) {
        pr = embedded;
        source = '页面数据';
      }
    }
    if (!pr) {
      throw new Error('拿不到播放数据：' + (errors[0] || '视频可能受限、需要登录或为直播'));
    }

    const details = pr.videoDetails || {};
    const title = details.title || document.title.replace(/ - YouTube$/, '');
    const base = safeName(title);

    const collected = collectYtFormats(pr);
    const g = collected.groups;

    g.muxed.forEach((it) => {
      it.filename = base + '_' + (it._h ? it._h + 'p' : 'muxed') + '.' + (it._ext || 'mp4');
    });
    g.video.forEach((it) => {
      it.filename = base + '_' + (it._h ? it._h + 'p' : 'video') + '_video.' + (it._ext || 'mp4');
    });
    g.audio.forEach((it) => {
      it.filename = base + '_audio.' + (it._ext === 'webm' ? 'webm' : 'm4a');
    });

    const hint = [];
    if (!g.muxed.length) hint.push('没有渐进式（画面+音轨）文件，需分别下载画面与声音后合并。');
    if (collected.ciphered > 0) hint.push('有 ' + collected.ciphered + ' 个流带签名保护，已跳过（浏览器内无法还原签名）。');
    if (pr.streamingData && pr.streamingData.hlsManifestUrl) hint.push('这是直播/分片流，暂不支持，请用底部 yt-dlp 命令。');
    hint.push('数据来源：' + source + '。');

    // 字幕（ANDROID 响应常不带 captions，回退读页面内嵌数据）
    UI.setLoading('正在获取字幕与封面…');
    let capTracks = ytCaptionTracks(pr);
    if (!capTracks.length) {
      const emb = readEmbeddedPlayerResponse();
      if (emb) capTracks = ytCaptionTracks(emb);
    }
    const subItems = capTracks.map((t) => ({
      label: t.name,
      sub: 'SRT / VTT · ' + t.lan,
      url: t.url,
      filename: base + '_' + t.lan + '.srt',
      onDownload: async () => {
        UI.toast('正在获取字幕：' + t.name);
        try {
          const f = await ytCaptionFile(t.url);
          saveText(base + '_' + t.lan + '.' + f.ext, f.text);
        } catch (e) {
          UI.toast('字幕获取失败：' + e.message);
        }
      },
    }));
    if (!subItems.length) hint.push('该视频没有可用字幕轨道（或字幕接口要求登录 / PO token）。');

    const coverItems = ytCoverItems(details, vid, base);

    const actions = [];
    const bestV = g.video[0];
    const bestA = g.audio[0];
    const needMkv = (bestV && bestV._ext === 'webm') || (bestA && bestA._ext === 'webm');
    const mergedName = base + '_合并.' + (needMkv ? 'mkv' : 'mp4');
    if (bestV && bestA) {
      actions.push({
        label: '下载最佳画面 + 声音',
        onClick: () => {
          download(bestV.url, bestV.filename, 'https://www.youtube.com/');
          setTimeout(() => download(bestA.url, bestA.filename, 'https://www.youtube.com/'), 1200);
          UI.toast('已开始下载两路流，需自行合并');
        },
      });
      actions.push({
        label: '复制 ffmpeg 合并命令',
        onClick: () => copyText('ffmpeg -i "' + bestV.filename + '" -i "' + bestA.filename + '" -c copy "' + mergedName + '"'),
      });
    }
    actions.push({
      label: '复制 yt-dlp 命令',
      onClick: () => copyText('yt-dlp -f "bv*+ba/b" --merge-output-format mp4 "https://www.youtube.com/watch?v=' + vid + '"'),
    });

    return {
      title: title,
      tag: 'YouTube',
      hint: hint.join(' '),
      groups: [
        { title: '单文件（画面 + 音轨）', items: g.muxed },
        { title: '仅画面（自适应，无音轨）', items: g.video },
        { title: '仅声音', items: g.audio },
        { title: '字幕', items: subItems },
        { title: '封面', items: coverItems },
      ],
      actions: actions,
      emptyText: '所有流都受签名保护，浏览器内无法直连下载。请用底部「复制 yt-dlp 命令」在本机执行。',
    };
  }

  /* ============================================================
   * 7. 流程控制
   * ============================================================ */
  function isVideoPage() {
    if (IS_YT) return !!getYtId();
    return /\/video\//.test(location.pathname) || /\/bangumi\/play\//.test(location.pathname) || /\/list\//.test(location.pathname);
  }

  let busy = false;
  let lastHref = location.href;

  async function refresh() {
    if (busy) return;
    if (!isVideoPage()) {
      UI.hideFab();
      UI.hide();
      return;
    }
    busy = true;
    UI.showFab();
    UI.show();
    UI.setLoading('正在解析…');
    try {
      const model = IS_YT ? await buildYtModel() : await buildBiliModel();
      UI.render(model);
      log('解析完成', model.title);
    } catch (e) {
      console.warn(TAG, e);
      UI.setError('解析失败：' + (e && e.message ? e.message : e));
    } finally {
      busy = false;
    }
  }

  function watchNavigation() {
    setInterval(() => {
      if (location.href === lastHref) return;
      lastHref = location.href;
      UI.reset();
      if (isVideoPage()) {
        UI.showFab();
        if (UI.isOpen()) refresh();
        else UI.hide();
      } else {
        UI.hideFab();
        UI.hide();
      }
    }, 1000);
  }

  function boot() {
    if (!HAS_GM) {
      console.warn(TAG, '缺少 GM_xmlhttpRequest，脚本无法工作');
      return;
    }
    UI.init({
      onOpen: () => refresh(),
      onReload: () => refresh(),
    });
    if (isVideoPage()) UI.showFab();
    watchNavigation();

    // 手动入口 + 自检（页面控制台可用）：__vdl.open() / __vdl.status()
    try {
      W.__vdl = {
        version: VERSION,
        open: () => {
          UI.showFab();
          UI.show();
          refresh();
        },
        show: () => {
          UI.showFab();
          UI.show();
        },
        status: () => UI.debug(),
        reload: () => refresh(),
      };
    } catch (e) {
      log('无法挂载 __vdl（不影响正常使用）', e.message);
    }

    // 站点把自己重新渲染、节点被摘掉时补挂
    setInterval(() => {
      UI.mount();
      if (isVideoPage()) UI.showFab();
    }, 2000);

    log('已加载 v' + VERSION + ' on', HOST + '，若未看到按钮请在控制台执行 __vdl.status()');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})();

