// ==UserScript==
// @name         Akagram Solver (frame-aware, manual trigger)
// @namespace    https://tampermonkey.net/
// @version      1.2
// @description  Solve Akagram on demand — press Ctrl+Shift+S or click the panel button
// @match        *://akagram.game-files.crazygames.com/*
// @match        *://*.crazygames.com/*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

(function () {
    'use strict';

    const CLICK_DELAY_MS = 12;
    const AUTO_SOLVE_WHEN_READY = false;

    const log = (...a) => console.log('%c[AK-SOLVER]', 'color:#4a90d9;font-weight:bold', ...a);

    let panel, statusEl, btn, autoEl, uiBuilt = false;

    // ---------------------------------------------------------
    // FRAME DETECTION
    // ---------------------------------------------------------
    function isGameFrame() {
        // Direct URL — unambiguous
        if (location.hostname === 'akagram.game-files.crazygames.com') return true;
        // Fallback: DOM markers that only exist in the actual game
        const app = document.querySelector('main#app');
        if (app) {
            if (app.querySelector('.home-screen, .game-screen, .board, .akagram-grid, .size-picker'))
                return true;
        }
        // Or a .board with real cells anywhere
        if (document.querySelector('.board > .cell, .akagram-grid .board')) return true;
        return false;
    }

    // ---------------------------------------------------------
    // EXTRACT
    // ---------------------------------------------------------
    function extract() {
        const board = document.querySelector('.board');
        if (!board) throw new Error('No .board on screen');
        const gridRoot = document.querySelector('.akagram-grid') || document;
        const items = [...board.children];
        const total = items.length;
        const n = Math.round(Math.sqrt(total));
        if (n * n !== total) throw new Error(`Board isn't square (${total} children)`);

        const rowHints = [...gridRoot.querySelectorAll('.row-hints .line-hint')]
            .map(e => parseInt(e.textContent.trim(), 10));
        const colHints = [...gridRoot.querySelectorAll('.column-hints .line-hint')]
            .map(e => parseInt(e.textContent.trim(), 10));
        if (rowHints.length !== n || colHints.length !== n)
            throw new Error(`Hint count mismatch (${rowHints.length}×${colHints.length} vs ${n}×${n})`);

        const grid = Array.from({ length: n }, () => new Array(n));
        for (let i = 0; i < total; i++) {
            const el = items[i];
            const r = Math.floor(i / n), c = i % n;
            const isWall = el.classList.contains('wall');
            const text = (el.textContent || '').trim();
            grid[r][c] = {
                type: isWall ? 'wall' : 'empty',
                clue: isWall && /^\d+$/.test(text) ? parseInt(text, 10) : null,
                el, r, c
            };
        }
        return { n, grid, rowHints, colHints };
    }

    // ---------------------------------------------------------
    // SOLVE
    // ---------------------------------------------------------
function solve({ n, grid, rowHints, colHints }) {
    const playables = [];
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++)
        if (grid[r][c].type === 'empty') playables.push([r, c]);

    const wallNb = [];
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
        if (grid[r][c].type !== 'wall' || grid[r][c].clue === null) continue;
        const cells = [];
        for (const [dr, dc] of [[-1,0],[1,0],[0,-1],[0,1]]) {
            const rr = r+dr, cc = c+dc;
            if (rr>=0 && rr<n && cc>=0 && cc<n && grid[rr][cc].type === 'empty') cells.push([rr, cc]);
        }
        wallNb.push({ clue: grid[r][c].clue, cells });
    }

    // ---- FIX: pre-initialize sight & covering for EVERY playable cell ----
    const sight = new Map(), covering = new Map();
    for (const [r, c] of playables) {
        const k = `${r},${c}`;
        sight.set(k, []);
        covering.set(k, [[r, c]]);
    }
    // ---- then populate ----
    for (const [r1, c1] of playables) {
        const k1 = `${r1},${c1}`;
        for (const [r2, c2] of playables) {
            if (r1 === r2 && c1 === c2) continue;
            if (r1 !== r2 && c1 !== c2) continue;
            const dr = Math.sign(r2 - r1), dc = Math.sign(c2 - c1);
            let r = r1 + dr, c = c1 + dc, ok = true;
            while (r !== r2 || c !== c2) {
                if (grid[r][c].type === 'wall') { ok = false; break; }
                r += dr; c += dc;
            }
            if (ok) {
                sight.get(k1).push([r2, c2]);
                covering.get(`${r2},${c2}`).push([r1, c1]);
            }
        }
    }

    function consistent(s) {
        for (const {clue, cells} of wallNb) {
            let b=0,u=0;
            for (const [r,c] of cells) { const v=s[r][c]; if(v===1)b++; else if(v===0)u++; }
            if (b>clue || b+u<clue) return false;
        }
        for (let r=0;r<n;r++){let b=0,u=0;for(let c=0;c<n;c++)if(grid[r][c].type==='empty'){const v=s[r][c];if(v===1)b++;else if(v===0)u++;}if(b>rowHints[r]||b+u<rowHints[r])return false;}
        for (let c=0;c<n;c++){let b=0,u=0;for(let r=0;r<n;r++)if(grid[r][c].type==='empty'){const v=s[r][c];if(v===1)b++;else if(v===0)u++;}if(b>colHints[c]||b+u<colHints[c])return false;}
        for (const [r,c] of playables){if(s[r][c]!==1)continue;for(const [r2,c2] of sight.get(`${r},${c}`))if(s[r2][c2]===1)return false;}
        for (const [r,c] of playables){let ok=false;for(const [r2,c2] of covering.get(`${r},${c}`))if(s[r2][c2]!==-1){ok=true;break;}if(!ok)return false;}
        return true;
    }

    function propagate(s) {
        let changed = true;
        while (changed) {
            changed = false;
            const set = (r,c,v) => {
                if (s[r][c] === v) return true;
                if (s[r][c] !== 0) return false;
                s[r][c] = v; changed = true; return true;
            };
            for (const {clue, cells} of wallNb) {
                let b=0; const u=[];
                for (const [r,c] of cells){if(s[r][c]===1)b++;else if(s[r][c]===0)u.push([r,c]);}
                if (b===clue) for (const [r,c] of u) if(!set(r,c,-1))return false;
                else if (b+u.length===clue) for (const [r,c] of u) if(!set(r,c,1))return false;
            }
            for (let r=0;r<n;r++){let b=0;const u=[];for(let c=0;c<n;c++)if(grid[r][c].type==='empty'){if(s[r][c]===1)b++;else if(s[r][c]===0)u.push([r,c]);}if(b===rowHints[r])for(const [rr,cc] of u)if(!set(rr,cc,-1))return false;else if(b+u.length===rowHints[r])for(const [rr,cc] of u)if(!set(rr,cc,1))return false;}
            for (let c=0;c<n;c++){let b=0;const u=[];for(let r=0;r<n;r++)if(grid[r][c].type==='empty'){if(s[r][c]===1)b++;else if(s[r][c]===0)u.push([r,c]);}if(b===colHints[c])for(const [rr,cc] of u)if(!set(rr,cc,-1))return false;else if(b+u.length===colHints[c])for(const [rr,cc] of u)if(!set(rr,cc,1))return false;}
            for (const [r,c] of playables) {
                if (s[r][c] !== 1) continue;
                for (const [r2,c2] of sight.get(`${r},${c}`)) {
                    if (s[r2][c2] === 1) return false;
                    if (s[r2][c2] === 0) { s[r2][c2] = -1; changed = true; }
                }
            }
        }
        return true;
    }

    function search(s) {
        if (!consistent(s)) return null;
        if (!propagate(s)) return null;
        if (!consistent(s)) return null;
        let un = null;
        for (const [r,c] of playables) if (s[r][c] === 0) { un = [r,c]; break; }
        if (!un) return s.map(row => row.slice());
        const [r,c] = un;
        for (const v of [1,-1]) {
            const copy = s.map(row => row.slice());
            copy[r][c] = v;
            const res = search(copy);
            if (res) return res;
        }
        return null;
    }

    const init = Array.from({length: n}, () => new Array(n).fill(0));
    return search(init);
}

    // ---------------------------------------------------------
    // APPLY
    // ---------------------------------------------------------
    function applySolution(puzzle, solution) {
        const bulbBtn = document.querySelector('[data-tool="bulb"]');
        if (bulbBtn && bulbBtn.getAttribute('aria-pressed') !== 'true') {
            bulbBtn.click();
            log('Activated bulb tool');
        }
        const app = document.querySelector('#app');
        if (app && app.hasAttribute('inert')) {
            app.removeAttribute('inert');
            log('Removed inert from #app');
        }

        const bulbs = [];
        for (let r = 0; r < puzzle.n; r++) for (let c = 0; c < puzzle.n; c++)
            if (solution[r][c] === 1) bulbs.push([r, c]);

        bulbs.forEach(([r, c], i) => {
            setTimeout(() => {
                const el = puzzle.grid[r][c].el;
                el.click();
                log(`  clicked (${r},${c})`);
            }, i * CLICK_DELAY_MS);
        });
        return bulbs.length;
    }

    // ---------------------------------------------------------
    // RUN
    // ---------------------------------------------------------
    function run() {
        setStatus('Running…', '#ffd700');
        try {
            const puzzle = extract();
            log('Board', puzzle.n + '×' + puzzle.n, '· rows', puzzle.rowHints, '· cols', puzzle.colHints);
            const solution = solve(puzzle);
            if (!solution) { setStatus('No solution', '#ff6b6b'); log('❌ No solution'); return; }
            const ascii = solution.map((row, r) => row.map((v, c) =>
                puzzle.grid[r][c].type === 'wall' ? '#' : v === 1 ? '●' : '.').join('')).join('\n');
            log('Solution:\n' + ascii);
            const n = applySolution(puzzle, solution);
            setStatus(`✅ ${n} bulbs placed`, '#8ec07c');
        } catch (e) {
            setStatus('Error: ' + e.message, '#ff6b6b');
            log('❌', e.message);
        }
    }

    function setStatus(txt, color) {
        if (!statusEl) return;
        statusEl.textContent = txt;
        statusEl.style.color = color || '#888';
    }

    // ---------------------------------------------------------
    // UI
    // ---------------------------------------------------------
    function buildPanel() {
        panel = document.createElement('div');
        panel.style.cssText = `
            position: fixed; bottom: 12px; right: 12px; z-index: 2147483647;
            background: #0d1117; color: #e6e6e6; padding: 10px 12px;
            border: 2px solid #4a90d9; border-radius: 8px;
            font: 12px/1.4 monospace; box-shadow: 0 6px 24px rgba(0,0,0,.7);
            min-width: 260px;
        `;
        panel.innerHTML = `
            <div style="font-weight:bold;color:#4a90d9;margin-bottom:6px;">
                🧩 Akagram Solver
            </div>
            <div id="ak-status" style="color:#888;margin-bottom:8px;font-size:11px;">
                Waiting for a puzzle…
            </div>
            <div style="display:flex;gap:6px;flex-wrap:wrap;">
                <button id="ak-solve" style="flex:1;padding:6px 10px;background:#238636;color:#fff;border:none;border-radius:4px;cursor:pointer;font-weight:bold;">
                    Solve now (Ctrl+Shift+S)
                </button>
                <button id="ak-hide" style="padding:6px 8px;background:#21262d;color:#e6e6e6;border:1px solid #30363d;border-radius:4px;cursor:pointer;">
                    Hide
                </button>
            </div>
            <label style="display:flex;align-items:center;gap:6px;margin-top:8px;font-size:11px;color:#888;">
                <input type="checkbox" id="ak-auto">
                Auto-solve when board appears
            </label>
        `;
        document.body.appendChild(panel);
        statusEl = panel.querySelector('#ak-status');
        btn = panel.querySelector('#ak-solve');
        autoEl = panel.querySelector('#ak-auto');
        btn.onclick = run;
        panel.querySelector('#ak-hide').onclick = () => {
            panel.style.display = 'none';
            const tab = document.createElement('div');
            tab.textContent = '🧩';
            tab.title = 'Show Akagram Solver';
            tab.style.cssText = 'position:fixed;bottom:12px;right:12px;z-index:2147483647;background:#0d1117;color:#4a90d9;padding:8px 10px;border:2px solid #4a90d9;border-radius:8px;cursor:pointer;font-size:16px;';
            tab.onclick = () => { panel.style.display = ''; tab.remove(); };
            document.body.appendChild(tab);
        };
    }

    function installHotkey() {
        document.addEventListener('keydown', e => {
            if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 's') {
                e.preventDefault();
                run();
            }
        }, true);
    }

    // ---------------------------------------------------------
    // WATCH FOR BOARD
    // ---------------------------------------------------------
    let lastBoardState = null, lastAutoRunKey = null;

    function watchBoard() {
        setInterval(() => {
            const board = document.querySelector('.board');
            const hasBoard = !!board;
            let state = 'no-board';
            if (hasBoard) {
                const items = board.children.length;
                const n = Math.round(Math.sqrt(items));
                state = n + '×' + n;
            }
            if (state !== lastBoardState) {
                lastBoardState = state;
                if (hasBoard) setStatus('✅ Board ready (' + state + ') — click Solve', '#8ec07c');
                else setStatus('Waiting for a puzzle…', '#888');
            }
            if (hasBoard && (autoEl?.checked || AUTO_SOLVE_WHEN_READY)) {
                if (lastAutoRunKey !== state) {
                    lastAutoRunKey = state;
                    setTimeout(run, 400);
                }
            } else if (!hasBoard) {
                lastAutoRunKey = null;
            }
        }, 500);
    }

    // ---------------------------------------------------------
    // POLL FOR GAME FRAME, THEN BUILD UI
    // ---------------------------------------------------------
    function tryBuild() {
        if (uiBuilt) return;
        if (!document.body) return;
        if (!isGameFrame()) return;
        uiBuilt = true;
        log(`🎮 Game frame detected: ${location.hostname}${location.pathname.slice(0, 40)} (top=${window === window.top})`);
        buildPanel();
        installHotkey();
        watchBoard();
    }

    // Log every frame's identity at load, but only build UI in game frame
    log(`loaded frame: ${location.hostname}${location.pathname.slice(0, 40)} | top=${window === window.top}`);

    setInterval(tryBuild, 400);
    if (document.readyState !== 'loading') setTimeout(tryBuild, 100);
    else document.addEventListener('DOMContentLoaded', () => setTimeout(tryBuild, 100));
})();

