// apps have one origin, so localStorage alone already is that copy.
const SHARED = /^gr:(settings|notes|notes-ui|history)$/;
const store = {
  get(k, d) { try { const v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch { return d; } },
  set(k, v) {
