  if (posts[2]) posts[2].body = `${fakeLine('q3', LANG)}\n\n---  \nSent from my phone`;
  if (posts[3] && at(1)) posts[3].body = `Reply #1: @${at(1).username}\n---\n${fakeLine('q4', LANG)}`;
  return json;
}
